def hysteresis_1d(magnitudes, low, high):
    n = len(magnitudes)
    if n == 0:
        return []
    if high < low:
        low, high = high, low
    strong = [m >= high for m in magnitudes]
    weak = [low <= m < high for m in magnitudes]
    edges = list(strong)
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if weak[i] and not edges[i]:
                left_edge = i > 0 and edges[i - 1]
                right_edge = i + 1 < n and edges[i + 1]
                if left_edge or right_edge:
                    edges[i] = True
                    changed = True
    return edges
